from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-width and full-height separator lines define the repeated panels.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    row_groups, col_groups = [], []
    start = 0
    for r in sep_rows + [h]:
        if start < r:
            row_groups.append(range(start, r))
        start = r + 1
    start = 0
    for c in sep_cols + [w]:
        if start < c:
            col_groups.append(range(start, c))
        start = c + 1
    separators = set(sep_rows) | set(sep_cols)
    values = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if r not in sep_rows and c not in sep_cols)
    background = values.most_common(1)[0][0]
    marker = min((n for n in values if n != background), key=lambda n: values[n])
    out = [[background for _ in col_groups] for _ in row_groups]
    for i, rows in enumerate(row_groups):
        for j, cols in enumerate(col_groups):
            count = sum(grid[r][c] == marker for r in rows for c in cols)
            if count == 2:
                out[i][j] = 1
    return out
